CREATE TABLE public.vertriebs_check_settings (id boolean PRIMARY KEY DEFAULT true CHECK(id), video_url text CHECK(video_url IS NULL OR (length(video_url)<=2048 AND video_url ~ '^https://')), calendar_url text NOT NULL DEFAULT 'https://calendar.app.google/i2jtG5DapbEjzWba6', updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.vertriebs_check_settings TO authenticated; GRANT ALL ON public.vertriebs_check_settings TO service_role;
ALTER TABLE public.vertriebs_check_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY vc_settings_admin ON public.vertriebs_check_settings FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.gebiete (plz_prefix text PRIMARY KEY CHECK(plz_prefix ~ '^[0-9]{3}$'), status text NOT NULL CHECK(status IN ('frei','vergeben')), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.gebiete TO authenticated; GRANT ALL ON public.gebiete TO service_role;
ALTER TABLE public.gebiete ENABLE ROW LEVEL SECURITY;
CREATE POLICY vc_gebiete_admin ON public.gebiete FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.vertriebs_check_consents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), choice text NOT NULL CHECK(choice IN ('all','necessary')), notice_version text NOT NULL DEFAULT 'vc-2026-10-31', accepted_at timestamptz NOT NULL DEFAULT now(), withdrawn_at timestamptz);
GRANT SELECT ON public.vertriebs_check_consents TO authenticated; GRANT ALL ON public.vertriebs_check_consents TO service_role;
ALTER TABLE public.vertriebs_check_consents ENABLE ROW LEVEL SECURITY;
CREATE POLICY vc_consents_admin ON public.vertriebs_check_consents FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.vertriebs_check_submissions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), token uuid NOT NULL UNIQUE DEFAULT gen_random_uuid(), request_id uuid NOT NULL UNIQUE, contact_id uuid NOT NULL REFERENCES public.crm_contacts(id), lead_id uuid NOT NULL REFERENCES public.crm_leads(id) ON DELETE CASCADE, first_name text NOT NULL CHECK(length(first_name) BETWEEN 1 AND 100), company text NOT NULL CHECK(length(company) BETWEEN 1 AND 200), postcode text NOT NULL CHECK(postcode ~ '^[0-9]{5}$'), email text NOT NULL CHECK(length(email)<=255), phone text NOT NULL CHECK(length(phone)<=32), answers integer[] NOT NULL CHECK(array_length(answers,1)=6 AND answers <@ ARRAY[0,1,2]), scores jsonb NOT NULL, total integer NOT NULL CHECK(total BETWEEN 0 AND 12), result_type text NOT NULL, status text NOT NULL DEFAULT 'neu' CHECK(status IN ('neu','termin_gebucht','angerufen','abgelehnt')), whatsapp_consent boolean NOT NULL DEFAULT false, email_consent boolean NOT NULL DEFAULT false, consent_evidence jsonb NOT NULL, attribution jsonb NOT NULL DEFAULT '{}', session_id uuid, advertising_consent_id uuid REFERENCES public.vertriebs_check_consents(id), unsubscribe_token uuid NOT NULL DEFAULT gen_random_uuid(), unsubscribed_at timestamptz, result_mail_status text NOT NULL DEFAULT 'pending', owner_mail_status text NOT NULL DEFAULT 'pending', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE,DELETE ON public.vertriebs_check_submissions TO authenticated; GRANT ALL ON public.vertriebs_check_submissions TO service_role;
ALTER TABLE public.vertriebs_check_submissions ENABLE ROW LEVEL SECURITY;
CREATE POLICY vc_submissions_admin ON public.vertriebs_check_submissions FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.vertriebs_check_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), session_id uuid NOT NULL, consent_id uuid NOT NULL REFERENCES public.vertriebs_check_consents(id), step text NOT NULL CHECK(step IN ('besuch','check_gestartet','frage_1','frage_2','frage_3','frage_4','frage_5','frage_6','eingetragen','auswertung_geoeffnet','termin_gebucht')), event_id uuid NOT NULL UNIQUE, attribution jsonb NOT NULL DEFAULT '{}', capi_status text NOT NULL DEFAULT 'pending', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(session_id,step));
CREATE INDEX vc_events_created_idx ON public.vertriebs_check_events(created_at);
GRANT SELECT ON public.vertriebs_check_events TO authenticated; GRANT ALL ON public.vertriebs_check_events TO service_role;
ALTER TABLE public.vertriebs_check_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY vc_events_admin ON public.vertriebs_check_events FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.vertriebs_check_sequence_steps (day integer PRIMARY KEY CHECK(day IN (1,2,4,6,9,14)), subject text NOT NULL DEFAULT '' CHECK(length(subject)<=200), body text NOT NULL DEFAULT '' CHECK(length(body)<=10000), enabled boolean NOT NULL DEFAULT false);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.vertriebs_check_sequence_steps TO authenticated; GRANT ALL ON public.vertriebs_check_sequence_steps TO service_role;
ALTER TABLE public.vertriebs_check_sequence_steps ENABLE ROW LEVEL SECURITY;
CREATE POLICY vc_sequence_admin ON public.vertriebs_check_sequence_steps FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.vertriebs_check_jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), submission_id uuid NOT NULL REFERENCES public.vertriebs_check_submissions(id) ON DELETE CASCADE, channel text NOT NULL CHECK(channel IN ('whatsapp','email')), day integer NOT NULL DEFAULT 0, due_at timestamptz NOT NULL, status text NOT NULL DEFAULT 'awaiting_provider' CHECK(status IN ('awaiting_provider','pending','sent','failed','cancelled')), body text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(submission_id,channel,day));
GRANT SELECT,UPDATE,DELETE ON public.vertriebs_check_jobs TO authenticated; GRANT ALL ON public.vertriebs_check_jobs TO service_role;
ALTER TABLE public.vertriebs_check_jobs ENABLE ROW LEVEL SECURITY;
CREATE POLICY vc_jobs_admin ON public.vertriebs_check_jobs FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
ALTER TABLE public.crm_leads ADD COLUMN vertriebs_check_data jsonb;
CREATE TABLE public.vertriebs_check_rate_limits (key text PRIMARY KEY, window_start timestamptz NOT NULL DEFAULT now(), attempts integer NOT NULL DEFAULT 1);
GRANT ALL ON public.vertriebs_check_rate_limits TO service_role; ALTER TABLE public.vertriebs_check_rate_limits ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.vc_rate_limit(_key text,_max integer) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n integer; BEGIN INSERT INTO vertriebs_check_rate_limits(key) VALUES(_key) ON CONFLICT(key) DO UPDATE SET attempts=CASE WHEN vertriebs_check_rate_limits.window_start < now()-interval '1 hour' THEN 1 ELSE vertriebs_check_rate_limits.attempts+1 END, window_start=CASE WHEN vertriebs_check_rate_limits.window_start < now()-interval '1 hour' THEN now() ELSE vertriebs_check_rate_limits.window_start END RETURNING attempts INTO n; RETURN n<=_max; END $$;
REVOKE ALL ON FUNCTION public.vc_rate_limit(text,integer) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.vc_rate_limit(text,integer) TO service_role;
CREATE OR REPLACE FUNCTION public.vc_submit(_data jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE a integer[]; c uuid; l uuid; s vertriebs_check_submissions; owner_id uuid; total_points integer; typ text; station_scores jsonb; evidence jsonb; ad uuid; attribution_data jsonb; sid uuid; red text; names text[] := ARRAY['Sichtbarkeit','Filter','Vertrauen','Tempo','Termin','Cockpit'];
BEGIN
SELECT * INTO s FROM vertriebs_check_submissions WHERE request_id=(_data->>'request_id')::uuid; IF FOUND THEN RETURN jsonb_build_object('token',s.token,'id',s.id,'lead_id',s.lead_id,'existing',true); END IF;
SELECT array_agg(value::integer ORDER BY ord) INTO a FROM jsonb_array_elements_text(_data->'answers') WITH ORDINALITY AS x(value,ord);
IF array_length(a,1) IS DISTINCT FROM 6 OR NOT (a <@ ARRAY[0,1,2]) OR _data->>'postcode' !~ '^[0-9]{5}$' OR coalesce((_data->>'privacy')::boolean,false)=false OR length(trim(_data->>'first_name')) NOT BETWEEN 1 AND 100 OR length(trim(_data->>'company')) NOT BETWEEN 1 AND 200 OR length(_data->>'email')>255 OR _data->>'email' !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' OR _data->>'phone' !~ '^\+?[0-9 ()/-]{7,32}$' THEN RAISE EXCEPTION 'invalid submission'; END IF;
SELECT sum(x) INTO total_points FROM unnest(a) x;
typ := CASE WHEN total_points<=4 THEN 'Empfehlungs-Vertrieb' WHEN total_points<=8 THEN 'Lead-Hamsterrad' ELSE 'Kurz vor Marktführer' END;
station_scores:=jsonb_build_object('sichtbarkeit',a[1],'filter',a[2],'vertrauen',a[3],'tempo',a[4],'termin',a[5],'cockpit',a[6]);
SELECT user_id INTO owner_id FROM user_roles WHERE role='admin' AND user_id IN (SELECT id FROM auth.users WHERE email='jonas@marketlab-media.de') LIMIT 1; IF owner_id IS NULL THEN RAISE EXCEPTION 'owner not configured'; END IF;
-- Reuse central matching with email and phone only, leaving existing caller behavior unchanged.
c:=crm_match_contact(NULL,_data->>'email',NULL,_data->>'phone',NULL,NULL);
IF c IS NULL THEN INSERT INTO crm_contacts(full_name,first_name,company,email,phone,segment,relationship,source,created_by) VALUES(trim(_data->>'first_name'),trim(_data->>'first_name'),trim(_data->>'company'),lower(trim(_data->>'email')),_data->>'phone','immo_finanz','lead','vertriebs-check',owner_id) RETURNING id INTO c; END IF;
IF nullif(_data->>'advertising_consent_id','') IS NOT NULL THEN SELECT id INTO ad FROM vertriebs_check_consents WHERE id=(_data->>'advertising_consent_id')::uuid AND choice='all' AND withdrawn_at IS NULL; END IF;
IF ad IS NOT NULL THEN attribution_data:=coalesce(_data->'attribution','{}'); sid:=nullif(_data->>'session_id','')::uuid; ELSE attribution_data:='{}'; sid:=NULL; END IF;
evidence:=jsonb_build_object('recorded_at',now(),'privacy',jsonb_build_object('accepted',true,'text','Ich habe die Datenschutzerklärung gelesen.'),'whatsapp',jsonb_build_object('accepted',coalesce((_data->>'whatsapp_consent')::boolean,false),'text','Schickt mir meine Auswertung auch per WhatsApp.'),'email',jsonb_build_object('accepted',coalesce((_data->>'email_consent')::boolean,false),'text','Ich möchte weitere Tipps zu meiner Auswertung per E-Mail, jederzeit abbestellbar.'));
SELECT string_agg(names[i],', ') INTO red FROM generate_series(1,6) i WHERE a[i]=0;
INSERT INTO crm_leads(name,contact_name,contact_email,contact_phone,contact_id,source,stage,created_by,next_step,description,vertriebs_check_data) VALUES(trim(_data->>'company'),trim(_data->>'first_name'),lower(trim(_data->>'email')),_data->>'phone',c,'vertriebs-check','neu',owner_id,'Vertriebs-Check: anrufen',typ || ' · ' || total_points || '/12 · Rote Stationen: ' || coalesce(red,'keine'),jsonb_build_object('answers',a,'scores',station_scores,'total',total_points,'type',typ,'postcode',_data->>'postcode','status','neu','consent_evidence',evidence,'attribution',attribution_data,'session_id',sid)) RETURNING id INTO l;
INSERT INTO vertriebs_check_submissions(request_id,contact_id,lead_id,first_name,company,postcode,email,phone,answers,scores,total,result_type,whatsapp_consent,email_consent,consent_evidence,attribution,session_id,advertising_consent_id) VALUES((_data->>'request_id')::uuid,c,l,trim(_data->>'first_name'),trim(_data->>'company'),_data->>'postcode',lower(trim(_data->>'email')),_data->>'phone',a,station_scores,total_points,typ,coalesce((_data->>'whatsapp_consent')::boolean,false),coalesce((_data->>'email_consent')::boolean,false),evidence,attribution_data,sid,ad) RETURNING * INTO s;
UPDATE crm_leads SET vertriebs_check_data=vertriebs_check_data || jsonb_build_object('submission_id',s.id,'result_path','/check/auswertung/'||s.token) WHERE id=l;
INSERT INTO crm_activities(lead_id,contact_id,type,title,body,created_by,metadata) VALUES(l,c,'note','Vertriebs-Check ausgefüllt',typ || ' · ' || total_points || '/12 · Rote Stationen: ' || coalesce(red,'keine'),owner_id,jsonb_build_object('scores',station_scores,'submission_id',s.id,'result_path','/check/auswertung/'||s.token));
INSERT INTO notifications(user_id,type,title,body,link,reference_id,reference_type) VALUES(owner_id,'info','Neuer Vertriebs-Check',s.first_name || ' · ' || s.company || ' · PLZ ' || s.postcode || ' · ' || s.phone || ' · ' || typ || ' · Rot: ' || coalesce(red,'keine'),'/crm/lead/'||l,l,'crm_lead');
IF s.whatsapp_consent THEN INSERT INTO vertriebs_check_jobs(submission_id,channel,due_at,body) VALUES(s.id,'whatsapp',now(),'Hallo ' || s.first_name || ', hier ist deine Auswertung: https://hub.marketlab-media.de/check/auswertung/'||s.token); END IF;
IF s.email_consent THEN INSERT INTO vertriebs_check_jobs(submission_id,channel,day,due_at) SELECT s.id,'email',d,now()+d*interval '1 day' FROM unnest(ARRAY[1,2,4,6,9,14]) d; END IF;
RETURN jsonb_build_object('token',s.token,'id',s.id,'lead_id',l,'existing',false);
END $$;
REVOKE ALL ON FUNCTION public.vc_submit(jsonb) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.vc_submit(jsonb) TO service_role;
CREATE OR REPLACE FUNCTION public.vc_sync_status() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.stage IS DISTINCT FROM OLD.stage AND OLD.source='vertriebs-check' THEN UPDATE vertriebs_check_submissions SET status=CASE WHEN NEW.stage IN ('neu','termin_gebucht','angerufen','abgelehnt') THEN NEW.stage ELSE 'angerufen' END WHERE lead_id=NEW.id; END IF; RETURN NEW; END $$;
CREATE TRIGGER vc_lead_status AFTER UPDATE OF stage ON public.crm_leads FOR EACH ROW EXECUTE FUNCTION public.vc_sync_status();
CREATE OR REPLACE FUNCTION public.vc_cancel_jobs() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.status<>'neu' OR NEW.unsubscribed_at IS NOT NULL OR NOT NEW.email_consent THEN UPDATE vertriebs_check_jobs SET status='cancelled' WHERE submission_id=NEW.id AND channel='email' AND status IN ('pending','awaiting_provider'); END IF; UPDATE crm_leads SET vertriebs_check_data=coalesce(vertriebs_check_data,'{}') || jsonb_build_object('status',NEW.status,'unsubscribed_at',NEW.unsubscribed_at) WHERE id=NEW.lead_id; RETURN NEW; END $$;
CREATE TRIGGER vc_submission_status AFTER UPDATE OF status,unsubscribed_at,email_consent ON public.vertriebs_check_submissions FOR EACH ROW EXECUTE FUNCTION public.vc_cancel_jobs();